const i = $input.first().json || {};
const S = (v) => (v === undefined || v === null ? '' : String(v));
let itens = [];
let opcoes = {};
try { const t = S(i.itens).trim(); if (t) { const p = JSON.parse(t); itens = Array.isArray(p) ? p : []; } } catch (e) { itens = []; }
try { const t = S(i.opcoes).trim(); if (t) { const p = JSON.parse(t); opcoes = p && typeof p === 'object' && !Array.isArray(p) ? p : {}; } } catch (e) { opcoes = {}; }
const ARTE = ['nenhuma', 'cliente', 'paga', 'com_frete'];
const op = {};
for (const k of ['bairro', 'cep', 'metodo', 'data_evento']) { if (opcoes[k]) op[k] = S(opcoes[k]).slice(0, 80); }
op.arte = ARTE.indexOf(opcoes.arte) >= 0 ? opcoes.arte : 'nenhuma';
op.conversation_id = i.conversation_id;
if (S(i.teste) === 'true') op.teste = true;
itens = itens.slice(0, 10).map((x) => ({
  sku: S(x && x.sku).trim(),
  quantidade: Math.max(1, Math.round(Number(x && x.quantidade) || 1)),
  acabamento: x && x.acabamento ? S(x.acabamento).trim() : undefined,
  largura_mm: x && x.largura_mm ? Number(x.largura_mm) : undefined,
  altura_mm: x && x.altura_mm ? Number(x.altura_mm) : undefined
})).filter((x) => x.sku);
const q = Number(i.quantidade);
return [{ json: Object.assign({}, i, { itens_arr: itens, opcoes_obj: op, quantidade_num: Number.isFinite(q) && q > 0 ? Math.round(q) : 0, fotos_num: Math.min(3, Math.max(1, Math.round(Number(i.quantidade_fotos) || 1))), inicio_ms: Date.now() }) }];

const ent = $('Reunir guarda e dados').first().json;
const it = $input.first();
const bruto = it && it.json ? it.json : {};
const ferr = String(ent.ferramenta || '');
const BLOQ = /^(custo|custos|cost|piso|piso_duro|margem|margem_liquida|margem_liquida_pct|lucro|lucro_liquido|fornecedor|fornecedor_ref|preco_base_custo|cabe_na_bike|entrega_sugerida|custo_entrega|custo_entrega_nosso|custo_total|lead_days|prazo_dias_uteis|endereco|endereco_retirada|bike|saidas_bike_por_dia|consulta_mercado_id|mercado_mediana|fontes_mercado|regra_preco|confianca_preco|nao_competitivo|peso_total_g|maior_lado_mm|piso_aplicado|bloqueio_motivo)$/i;
const DINHEIRO = /(preco|valor|total|subtotal|frete|arte|desconto|minimo|falta|parcela)/i;
const skus = new Set();
const valores = new Set();
const num = (n) => { if (Number.isFinite(n)) valores.add(Math.round(n * 100) / 100); };
function limpo(v, chave) {
  if (v === null || v === undefined) return v;
  if (Array.isArray(v)) return v.map((x) => limpo(x, chave));
  if (typeof v === 'object') {
    const o = {};
    for (const k of Object.keys(v)) {
      if (BLOQ.test(k) && !(ferr === 'salvar_contato' && k === 'endereco')) continue;
      if (/^sku$/i.test(k)) { if (v[k]) skus.add(String(v[k])); if (ferr !== 'buscar_produto') continue; }
      o[k] = limpo(v[k], k);
    }
    return o;
  }
  if (typeof v === 'number') { if (DINHEIRO.test(chave || '')) num(v); return v; }
  if (typeof v === 'string') {
    if (DINHEIRO.test(chave || '') && /^\d+([.,]\d{1,2})?$/.test(v.trim())) num(parseFloat(v.replace(',', '.')));
    const re = /R\$\s*(\d[\d.]*(?:,\d{1,2})?)/g;
    let m;
    while ((m = re.exec(v)) !== null) num(parseFloat(m[1].replace(/\./g, '').replace(',', '.')));
    return v.replace(/bicicleta|bike|ciclista/gi, 'entrega');
  }
  return v;
}
const falhou = !!(bruto.error || bruto.erro === 'indisponivel' || bruto.erro === 'ferramenta_indisponivel' || Object.keys(bruto).length === 0 || (bruto.status === 'bloqueado' && bruto.motivo === 'erro_interno'));
let resultado;
if (falhou) {
  resultado = { erro: 'ferramenta_indisponivel', orientacao: 'NUNCA invente valor, prazo ou informação. Diga ao cliente, de forma natural, que vai confirmar e já retorna. O dono já foi avisado.' };
} else {
  resultado = limpo(bruto, '');
}
const ms = Date.now() - Number(ent.inicio_ms || Date.now());
return [{ json: { falha: falhou, ferramenta: ferr, execucao_id: ent.execucao_id, conversation_id: ent.conversation_id, resultado: resultado, skus: Array.from(skus), valores: Array.from(valores), duracao_ms: ms, gravidade: (ferr === 'buscar_conhecimento' || ferr === 'enviar_foto_produto') ? 'baixa' : 'alta', resumo: falhou ? 'falhou' : Object.keys(resultado).slice(0, 8).join(',') } }];

let r = null;
try { r = $('Normalizar e proteger').first().json.resultado; } catch (e) { r = null; }
if (!r) { const x = $input.first(); r = x && x.json && x.json.resultado ? x.json.resultado : { erro: 'ferramenta_indisponivel', orientacao: 'Diga ao cliente que vai confirmar. Não invente nada.' }; }
return [{ json: r }];

const f = $input.first().json.ferramenta;
const R = {
  gerar_pdf_orcamento: { ok: true, enviado: true, simulado: true, numero: 'SG-TESTE' },
  enviar_foto_produto: { enviadas: 2, legenda_sugerida: 'Olha como fica por aqui', simulado: true },
  gerar_link_pagamento: { ok: true, link: 'https://exemplo.com.br/pagar/teste', valida_ate: 'amanhã', texto_curto: 'Link de pagamento pronto', simulado: true },
  arte_receber: { ok: true, pedido: 'SG-TESTE', qualidade: 'indefinida', na_fila: true, baixa_qualidade: false, orientacao: 'Diga que recebeu e que a equipe vai conferir e mandar a arte para aprovar. Não prometa data nova nem diga que a arte está aprovada.', simulado: true },
  arte_baixa_ok: { ok: true, registrado: true, simulado: true }
};
return [{ json: R[f] || { ok: true, simulado: true } }];

const e = $input.first().json;
const V = ['Já te passo o valor certinho, só um minutinho.', 'Deixa eu conferir o valor certinho aqui e já te falo.', 'Um instante que já separo o valor pra você.', 'Já te mando o valor certinho, tá?'];
let h = 0;
for (const c of String(e.execucao_id || 'x')) { h = (h * 31 + c.charCodeAt(0)) % 997; }
const texto = V[h % V.length];
const base = 'https://bhlosshvwmlyzhbghsrc.supabase.co';
const teste = e.teste === 'true';
return [{ json: { espera_url: teste ? base + '/rest/v1/rpc/agente_teste_registrar_saida' : base + '/functions/v1/agente-enviar', espera_body: teste ? { p_conversation: e.conversation_id, p_texto: texto } : { conversation_id: e.conversation_id, text: texto } } }];
